package com.hbm.client.radar;
import com.mojang.blaze3d.vertex.*;import java.util.*;import net.minecraft.client.renderer.*;import net.minecraft.resources.ResourceLocation;
/** Original screen-overlay depth test, source alpha blending and no depth writes while linked. */
final class RadarDisplayTypes extends RenderType{private RadarDisplayTypes(){super("unused",DefaultVertexFormat.POSITION_COLOR,VertexFormat.Mode.QUADS,256,false,false,()->{},()->{});}static final RenderType SCAN=create("hbm_radar_scan",DefaultVertexFormat.POSITION_COLOR,VertexFormat.Mode.QUADS,256,false,true,CompositeState.builder().setShaderState(new ShaderStateShard(GameRenderer::getPositionColorShader)).setTransparencyState(TRANSLUCENT_TRANSPARENCY).setCullState(NO_CULL).setWriteMaskState(COLOR_WRITE).createCompositeState(false));static final RenderType LINKED=texture(false),NOISE=texture(true);private static RenderType texture(boolean depth){return create(depth?"hbm_radar_noise":"hbm_radar_blips",DefaultVertexFormat.POSITION_TEX_COLOR,VertexFormat.Mode.QUADS,4096,false,!depth,CompositeState.builder().setShaderState(new ShaderStateShard(GameRenderer::getPositionTexColorShader)).setTextureState(new TextureStateShard(RadarScreen.TEXTURE,false,false)).setTransparencyState(depth?NO_TRANSPARENCY:TRANSLUCENT_TRANSPARENCY).setCullState(NO_CULL).setWriteMaskState(depth?COLOR_DEPTH_WRITE:COLOR_WRITE).createCompositeState(false));}}
